// Union describes one tagged union reachable from a response.
type Union struct {
	Tag      string              // discriminator property
	Payload  string              // "" when variant fields sit next to the tag, else the nested key
	Variants map[string][]string // tag value (JSON text for a boolean tag) -> required payload keys
	Flat     bool                // one Go struct for every variant
}

// Unions is every union reachable from a response, by Go name.
var Unions = map[string]*Union{
	"ChatConfiguration":            {Tag: "platform", Variants: map[string][]string{"slack": nil, "telegram": nil}},
	"MCPConnectionReconnectResult": {Tag: "status", Variants: map[string][]string{"connected": {"connection"}, "needs_auth": {"connection"}}, Flat: true},
	"MCPConnectionTest":            {Tag: "ok", Variants: map[string][]string{"false": {"error"}, "true": {"latencyMs", "server", "toolCount", "toolNames"}}, Flat: true},
	"NetworkPolicy":                {Tag: "mode", Variants: map[string][]string{"allowlist": {"allowedHosts"}, "offline": nil, "unrestricted": nil}},
	"Schedule":                     {Tag: "kind", Payload: "config", Variants: map[string][]string{"cron": {"expression"}, "interval": {"everyMs"}, "once": {"at"}}},
	"SkillCopyResult":              {Tag: "status", Variants: map[string][]string{"created": {"agentId", "skill"}, "failed": {"agentId", "error"}}},
	"ToolReference":                {Tag: "type", Variants: map[string][]string{"builtin": {"name"}, "function": {"name"}, "mcp": {"connectionId", "name"}}},
}

